// src/hooks/useChordGenerator.js

import { useState } from 'react';
import {
  allChords,
  chordDiagrams,
  keyPairs,
  keySignatures,
  SHARP,
  FLAT,
  DIM,
} from '../data/vocabulary';

const TONIC = 'T';
const SUBDOMINANT = 'S';
const DOMINANT = 'D';

const TRANSITION_MATRIX = {
  [TONIC]: { [TONIC]: 1, [SUBDOMINANT]: 3, [DOMINANT]: 2 },
  [SUBDOMINANT]: { [TONIC]: 2, [SUBDOMINANT]: 1, [DOMINANT]: 4 },
  [DOMINANT]: { [TONIC]: 5, [SUBDOMINANT]: 1, [DOMINANT]: 1 },
};

function getChordFunction(step) {
  if ([1, 3, 6].includes(step)) return TONIC;
  if ([2, 4].includes(step)) return SUBDOMINANT;
  if ([5, 7].includes(step)) return DOMINANT;
  return null;
}

export default function useChordGenerator() {
  const [state, setState] = useState('chooseKeyNum');

  const [key, setKey] = useState('');
  const [selectedChords, setSelectedChords] = useState([]);
  const [selectedSteps, setSelectedSteps] = useState([]);
  const [forbidVtoIV, setForbidVtoIV] = useState(true);
  const [sequenceLength, setSequenceLength] = useState(4);
  const [sequence, setSequence] = useState([]);



  const cadenceTypes = {
    autentic: { name: 'Автентический', templateSteps: [5, 1], desc: 'Классическое разрешение доминанты в тонику.' },
    plagal: { name: 'Плагальный', templateSteps: [4, 1], desc: 'Разрешение субдоминанты в тонику.' },
    full: { name: 'Полный функциональный оборот', templateSteps: [4, 5, 1], desc: 'SDT' },
    interrupted: { name: 'Прерванный', templateSteps: [5, 6], desc: 'Ожидание разрешения в тонику, но уход в другой аккорд, обычно в VI.' },
    dominant: { name: 'Доминантовый', templateSteps: [5], desc: 'Завершение на аккорде доминанты, создающее напряжение.' },
    leading: { name: 'Вводный', templateSteps: [7, 1], desc: 'Начинается с аккорда VII ступени, разрешается в тонику.' },
  };

  // Вспомогательная функция для генерации следующего аккорда
  const chooseNextChord = (prevStep) => {
    if (!selectedChords.length || !selectedSteps.length) return null;

    if (prevStep === null) {
      const idx = Math.floor(Math.random() * selectedChords.length);
      return { chord: selectedChords[idx], step: selectedSteps[idx] };
    }

    const prevFunction = getChordFunction(prevStep);
    if (!prevFunction) return null;

    let candidates = [];
    selectedSteps.forEach((step, idx) => {
      const stepFunction = getChordFunction(step);
      let weight = TRANSITION_MATRIX[prevFunction][stepFunction] || 0;

      // ЗАПРЕТ V -> IV
      if (forbidVtoIV && prevFunction === DOMINANT && stepFunction === SUBDOMINANT) {
        weight = 0;
      }

      for (let i = 0; i < weight; i++) candidates.push(idx);
    });

    if (candidates.length === 0) return null;

    const chosenIdx = candidates[Math.floor(Math.random() * candidates.length)];
    return {
      chord: selectedChords[chosenIdx],
      step: selectedSteps[chosenIdx],
    };
  };

  // Функция проверки возможности применить каданс
  const canApplyCadence = () => {
    return Object.values(cadenceTypes).some(cadence =>
      cadence.templateSteps.every(step => selectedSteps.includes(step))
    );
  };

  // Основная логика генерации последовательности
  const generateSequence = () => {
    if (!key || !selectedChords.length) return;

    let sequenceChords = [];
    let currentStep = null;

    while (sequenceChords.length < sequenceLength) {
      const nextItem = chooseNextChord(currentStep);
      if (!nextItem) break;

      sequenceChords.push(nextItem.chord);
      currentStep = nextItem.step;
    }

    // --- ПРИМЕНЕНИЕ КАДАНСА ---
    // --- ПРИМЕНЕНИЕ КАДАНСА ---
    if (forbidVtoIV && canApplyCadence()) {
      const randomCadenceName = Object.keys(cadenceTypes)[Math.floor(Math.random() * Object.keys(cadenceTypes).length)];
      const cadenceInfo = cadenceTypes[randomCadenceName];

      // Отрезаем последние аккорды по длине каданса
      sequenceChords.splice(-cadenceInfo.templateSteps.length);

      cadenceInfo.templateSteps.forEach(stepNum => {
        const indexInSelected = selectedSteps.indexOf(stepNum);
        if (indexInSelected !== -1) {
          sequenceChords.push(selectedChords[indexInSelected]);
        }
      });
    }

    setSequence(sequenceChords);
    setState('askRepeat'); // Состояние после генерации
    console.log("Готово устанавливать последовательность:", sequenceChords);
  };

  // Обработчик ввода пользователя
  const handleInput = (userInput) => {
    console.log(`--- НОВЫЙ ВВОД: '${userInput}' | Текущее состояние: '${state}' ---`);

    // --- НОВОЕ: Проверяем ввод '00' В САМОМ НАЧАЛЕ, независимо от состояния ---
    if (userInput === '00') {
      console.log("Ввод '00' распознан. Запуск быстрой генерации...");
      // 1. Выбираем случайную тональность
      const randomIdx = Math.floor(Math.random() * keyPairs.length);
      const randomMode = Math.round(Math.random());
      const newKey = keyPairs[randomIdx][randomMode];
      console.log(`1. Тональность выбрана: ${newKey}`);
      setKey(newKey);

      // 2. Выбираем все аккорды этой тональности
      const chordsInKey = allChords[newKey];
      console.log(`2. Аккорды загружены.`, chordsInKey);
      setSelectedChords(chordsInKey.slice());
      setSelectedSteps([1,2,3,4,5,6,7]);

      // 3. Устанавливаем длину
      setSequenceLength(4);
      console.log("3. Длина установлена.");

      // 4. Сразу генерируем
      console.log("4. Вызываем generateSequence()...");
      generateSequence();
      return; // Обязательно выходим из функции!
    }

    // --- СТАРАЯ ЛОГИКА (теперь она работает только для других вводов) ---
    switch (state) {
      case 'chooseKeyNum':
        console.log("Состояние 'chooseKeyNum': Переходим в 'chooseChords'");
        setState('chooseChords');
        break;

      case 'chooseChords':
        console.log("Состояние 'chooseChords': Пытаемся сгенерировать...");
        generateSequence();
        break;

      case 'askVtoIV':
        console.log(`Состояние 'askVtoIV': Меняем настройку forbidVtoIV.`);
        setForbidVtoIV(userInput !== '2' && userInput !== 'нет');
        setState('askCount');
        break;

      case 'askCount':
        console.log(`Состояние 'askCount': Устанавливаем длину.`);
        const num = parseInt(userInput);
        if (!isNaN(num) && num >= 3) setSequenceLength(num);
        console.log("Пытаемся сгенерировать после установки длины...");
        generateSequence();
        break;

      case 'askRepeat':
        console.log(`Состояние 'askRepeat': Пользователь ввел '${userInput}'.`);
        if (userInput === '1') {
          console.log("Пользователь нажал 'Сгенерировать снова'.");
          generateSequence();
        } else if (userInput === '2') {
          console.log("Пользователь нажал 'Выбрать другие аккорды'.");
          setState('chooseChords');
        } else if (userInput === '3') {
          console.log("Пользователь нажал 'Выбрать другую тональность'.");
          setState('chooseKeyNum');
        }
        break;

      default:
        // Эта ветка теперь будет срабатывать только если state что-то неожиданное
        console.log(`Unhandled state: ${state} with input: ${userInput}`);
    }
  };

  return {
    state,
    key,
    sequence,
    sequenceLength,
    forbidVtoIV,
    handleInput,
  };
}
